Tool response:
Tool: update_invoice_shipping_and_payment
Description: Update Invoice Shipping And Payment
Parameters:
    {
      "type": "object",
      "properties": {
        "invoice_id": {
          "type": "string",
          "title": "Invoice Id",
          "description": ""
        },
        "shipping_address": {
          "type": "string",
          "title": "Shipping Address"
        },
        "shipping_city": {
          "type": "string",
          "title": "Shipping City"
        },
        "shipping_state": {
          "type": "string",
          "title": "Shipping State"
        },
        "shipping_zip": {
          "type": "string",
          "title": "Shipping Zip"
        },
        "shipping_method": {
          "type": "string",
          "enum": [
            "standard",
            "express",
            "overnight"
          ],
          "title": "Shipping Method"
        },
        "payment_method": {
          "type": "string",
          "enum": [
            "paypal",
            "credit_card"
          ],
          "title": "Payment Method"
        }
      },
      "required": [
        "invoice_id",
        "shipping_address",
        "shipping_city",
        "shipping_state",
        "shipping_zip",
        "shipping_method",
        "payment_method"
      ]
    }

